function dockerfile(ctx) {
  return (
    `# ` +
    ctx.name +
    ` — multi-stage per platform/conventions/01-dockerfile-pattern.md.
# Lockfile: LOCAL pnpm-lock.yaml (this directory, pnpm install --ignore-workspace) because
# build context = services/` +
    ctx.name +
    ` — the root workspace lockfile is outside the context.
# Healthcheck is NOT declared here (conventions/01 rule 4) — single source of truth:
# platform/docker-compose.yml.

FROM node:22-alpine AS deps
WORKDIR /app
COPY package.json pnpm-lock.yaml ./
RUN corepack enable && pnpm install --frozen-lockfile

FROM deps AS build
COPY tsconfig.json ./
COPY src ./src
RUN pnpm exec tsc -p tsconfig.json

FROM node:22-alpine AS runtime
WORKDIR /app
ENV NODE_ENV=production
COPY --from=deps /app/node_modules ./node_modules
COPY --from=build /app/dist ./dist
COPY package.json ./
USER node
EXPOSE ` +
    ctx.port +
    `
CMD ["node", "dist/server.js"]
`
  );
}

function envTs(ctx) {
  const dbInterface = ctx.db ? `  dbUrl: string;\n` : `  dbUrl: string | null;\n`;
  const dbNeed = ctx.db ? `  const dbUrl = need('DATABASE_URL');\n` : `  // add DATABASE_URL (required, fail-fast) as soon as the service gets a database — conventions/06.\n`;
  const dbField = ctx.db ? `    dbUrl,\n` : `    dbUrl: null,\n`;
  return (
    `// env.ts — parse + fail-fast env config (conventions/06: 100% env-var, no silent
// fallback for secrets). Generated by scripts/generators gen-service.
export interface Env {
  port: number;
  jwtSecret: string;
  corsDevOrigin: string; // empty = deny-by-default (conventions/07)
  logLevel: 'debug' | 'info' | 'warn' | 'error';
  dbUrl: ` +
    (ctx.db ? 'string' : 'string | null') +
    `;
}

const LEVELS = ['debug', 'info', 'warn', 'error'] as const;

export function loadEnv(source: NodeJS.ProcessEnv = process.env): Env {
  const missing: string[] = [];
  const need = (name: string): string => {
    const v = source[name];
    if (!v || v.trim() === '') missing.push(name);
    return v ?? '';
  };

  const port = Number(need('PORT') || '` +
    ctx.port +
    `');
  const jwtSecret = need('JWT_SECRET');
` +
    dbNeed +
    `  const logLevelRaw = source.LOG_LEVEL ?? 'info';

  if (Number.isNaN(port) || port <= 0) {
    throw new Error('PORT invalid: "' + source.PORT + '" (conventions/05: ` +
    ctx.name +
    ` = ` +
    ctx.port +
    `)');
  }
  if (!LEVELS.includes(logLevelRaw as Env['logLevel'])) {
    throw new Error('LOG_LEVEL invalid: "' + logLevelRaw + '" (debug|info|warn|error)');
  }
  if (missing.length > 0) {
    throw new Error('Missing required env vars: ' + missing.join(', ') + ' (platform/.env.example)');
  }

  return {
    port,
    jwtSecret,
    corsDevOrigin: source.CORS_DEV_ORIGIN ?? '',
    logLevel: logLevelRaw as Env['logLevel'],
` +
    dbField +
    `  };
}
`
  );
}

