const authTs = () =>
  `// auth.ts — the service verifies the JWT itself (HS256 signature + expiry). The
// gateway only does a presence check — real verification is each service's job
// (conventions/08 rule 4, contracts/auth/token-contract.md §4). Generated by gen-service.
import type { FastifyReply, FastifyRequest } from 'fastify';
import jwt from 'jsonwebtoken';

export interface AuthUser {
  sub: string;
  email: string;
  roles: string[];
}

export function verifyJwt(token: string, secret: string): AuthUser {
  const payload = jwt.verify(token, secret) as Record<string, unknown>;
  return {
    sub: String(payload.sub ?? ''),
    email: String(payload.email ?? ''),
    roles: Array.isArray(payload.roles) ? payload.roles.map(String) : [],
  };
}

function unauthorized(reply: FastifyReply, requestId: string, message: string): void {
  reply.status(401).send({
    error: { code: 'UNAUTHORIZED', message, requestId, details: null },
  });
}

/** preHandler guard — missing/invalid/expired token → 401 envelope (conventions/04). */
export function requireAuth(secret: string) {
  return async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const header = request.headers.authorization;
    const token = typeof header === 'string' && header.startsWith('Bearer ') ? header.slice(7) : null;
    if (!token) {
      unauthorized(reply, request.id, 'Missing Authorization header');
      return;
    }
    try {
      verifyJwt(token, secret);
    } catch {
      unauthorized(reply, request.id, 'Invalid or expired token');
    }
  };
}
`;

function healthTs(ctx) {
  return (
    `// health.ts — /healthz (liveness) + /readyz (readiness), conventions/02.
// Registered TWICE: naked path (compose healthcheck + CI boot-smoke — the gateway
// does NOT route this path) and the /api/` +
    ctx.name +
    `/* mirror (rule 6 — the OpenAPI
// servers.url carries the prefix, so contract tests need the mirror). Both are auth-free.
// readyz = repo.ping() for REAL — when the service gains dependencies, probe them
// for real there; never hardcode 200 (conventions/02 rule 2).
import type { FastifyInstance } from 'fastify';

export interface Ready {
  /** Throw when not ready → readyz maps to a 503 DEPENDENCY_DOWN envelope. */
  check: () => Promise<void>;
}

function ok(): { status: 'ok' } {
  return { status: 'ok' };
}

export function registerHealthRoutes(app: FastifyInstance, ready: Ready): void {
  app.get('/healthz', async () => ok());

  app.get('/readyz', async (_request, reply) => {
    try {
      await ready.check();
      return ok();
    } catch (err) {
      reply.status(503);
      return {
        error: {
          code: 'DEPENDENCY_DOWN',
          message: 'not ready' + (err instanceof Error ? ': ' + err.message : ''),
          requestId: null,
          details: null,
        },
      };
    }
  });
}
`
  );
}

const repoTs = (ctx) =>
  `// repo.ts — repository contract for the default \`items\` resource. The route layer
// depends ONLY on this interface → unit tests inject an in-memory fake (pattern
// node-svc). Replace \`name\` with your real domain fields (contract-first: update
// contracts/openapi/` +
  ctx.name +
  `.yaml FIRST, then this file).
export interface Item {
  id: string;
  name: string;
  createdAt: string;
  updatedAt: string;
}

export interface ItemPage {
  items: Item[];
  total: number;
}

export interface ItemsRepo {
  /** Paginated list — tasks pattern (?limit/&offset), newest first. */
  list(limit: number, offset: number): Promise<ItemPage>;
  get(id: string): Promise<Item | null>;
  create(name: string): Promise<Item>;
  /** Partial update — only \`name\` is patchable in the default resource. Missing id → null. */
  update(id: string, name: string): Promise<Item | null>;
  /** Missing id → false. */
  remove(id: string): Promise<boolean>;
  /** Readiness probe — SELECT 1 (conventions/02 rule 2). */
  ping(): Promise<void>;
}
`;

const repoPgTs = (ctx) =>
  `// repo.pg.ts — pg implementation of ItemsRepo. Table identifier is generated
// (schema-per-service: \`` +
  itemsTable(ctx) +
  `\`) and asserted to a safe charset — identifiers are
// interpolated (SQL identifiers cannot be bound as parameters), values always are.
import type { Pool, PoolClient } from 'pg';
import type { Item, ItemPage, ItemsRepo } from './repo.js';

interface ItemRow {
  id: string;
  name: string;
  createdAt: Date | string;
  updatedAt: Date | string;
}

function toItem(row: ItemRow): Item {
  return {
    id: row.id,
    name: row.name,
    createdAt: new Date(row.createdAt).toISOString(),
    updatedAt: new Date(row.updatedAt).toISOString(),
  };
}

export class PgItemsRepo implements ItemsRepo {
  private readonly pool: Pool;
  private readonly table: string;

  constructor(pool: Pool, table: string) {
    // identifier guard — the table name comes from generation, assert anyway
    if (!/^[a-z0-9_]+(\\.[a-z0-9_]+)?$/.test(table)) {
      throw new Error('invalid table identifier: ' + table);
    }
    this.pool = pool;
    this.table = table;
  }

  async list(limit: number, offset: number): Promise<ItemPage> {
    const rows = await this.pool.query<ItemRow>(
      'SELECT id, name, created_at "createdAt", updated_at "updatedAt" FROM ' +
        this.table +
        ' ORDER BY created_at DESC LIMIT $1 OFFSET $2',
      [limit, offset],
    );
    const total = await this.pool.query<{ count: string }>('SELECT count(*) FROM ' + this.table);
    return { items: rows.rows.map(toItem), total: Number(total.rows[0].count) };
  }

  async get(id: string): Promise<Item | null> {
    const rows = await this.pool.query<ItemRow>(
      'SELECT id, name, created_at "createdAt", updated_at "updatedAt" FROM ' + this.table + ' WHERE id = $1',
      [id],
    );
    return rows.rows[0] ? toItem(rows.rows[0]) : null;
  }

  async create(name: string): Promise<Item> {
    const rows = await this.pool.query<ItemRow>(
      'INSERT INTO ' +
        this.table +
        ' (name) VALUES ($1) RETURNING id, name, created_at "createdAt", updated_at "updatedAt"',
      [name],
    );
    return toItem(rows.rows[0]);
  }

  async update(id: string, name: string): Promise<Item | null> {
    const rows = await this.pool.query<ItemRow>(
      'UPDATE ' +
        this.table +
        ' SET name = $2, updated_at = now() WHERE id = $1 RETURNING id, name, created_at "createdAt", updated_at "updatedAt"',
      [id, name],
    );
    return rows.rows[0] ? toItem(rows.rows[0]) : null;
  }

  async remove(id: string): Promise<boolean> {
    const rows = await this.pool.query('DELETE FROM ' + this.table + ' WHERE id = $1 RETURNING id', [id]);
    return (rows.rowCount ?? 0) > 0;
  }

  async ping(): Promise<void> {
    await this.pool.query('SELECT 1');
  }
}

/** Exported for shutdown paths that need the raw pool/client. */
export type { PoolClient };
`;

function itemsRoutesTs(ctx) {
  return (
    `// items.ts — default resource routes (REAL CRUD, tasks pattern): paginated list,
// get, create, patch, delete. Swap the resource for your real domain: update
// contracts/openapi/` +
    ctx.name +
    `.yaml FIRST (contract-first), then generate:types, then edit here +
// repo.ts/repo.pg.ts. Generated by gen-service.
import type { FastifyInstance } from 'fastify';
import { requireAuth } from '../auth.js';
import type { ItemsRepo } from '../repo.js';

export function registerItemRoutes(app: FastifyInstance, opts: { jwtSecret: string; repo: ItemsRepo }): void {
  const guard = requireAuth(opts.jwtSecret);

  app.get(
    '/items',
    {
      preHandler: [guard],
      schema: {
        querystring: {
          type: 'object',
          properties: {
            limit: { type: 'integer', minimum: 1, maximum: 100, default: 20 },
            offset: { type: 'integer', minimum: 0, default: 0 },
          },
        },
      },
    },
    async (request) => {
      const q = request.query as { limit: number; offset: number };
      return opts.repo.list(q.limit, q.offset);
    },
  );

  app.get(
    '/items/:itemId',
    {
      preHandler: [guard],
      schema: { params: { type: 'object', properties: { itemId: { type: 'string', format: 'uuid' } }, required: ['itemId'] } },
    },
    async (request, reply) => {
      const { itemId } = request.params as { itemId: string };
      const item = await opts.repo.get(itemId);
      if (!item) {
        reply.status(404);
        return { error: { code: 'NOT_FOUND', message: 'Item ' + itemId + ' does not exist', requestId: request.id, details: null } };
      }
      return item;
    },
  );

  app.post(
    '/items',
    {
      preHandler: [guard],
      schema: {
        body: {
          type: 'object',
          required: ['name'],
          properties: { name: { type: 'string', minLength: 1, maxLength: 200 } },
        },
      },
    },
    async (request, reply) => {
      const body = request.body as { name: string };
      const item = await opts.repo.create(body.name);
      reply.status(201);
      return item;
    },
  );

  app.patch(
    '/items/:itemId',
    {
      preHandler: [guard],
      schema: {
        params: { type: 'object', properties: { itemId: { type: 'string', format: 'uuid' } }, required: ['itemId'] },
        body: {
          type: 'object',
          required: ['name'],
          properties: { name: { type: 'string', minLength: 1, maxLength: 200 } },
        },
      },
    },
    async (request, reply) => {
      const { itemId } = request.params as { itemId: string };
      const body = request.body as { name: string };
      const item = await opts.repo.update(itemId, body.name);
      if (!item) {
        reply.status(404);
        return { error: { code: 'NOT_FOUND', message: 'Item ' + itemId + ' does not exist', requestId: request.id, details: null } };
      }
      return item;
    },
  );

  app.delete(
    '/items/:itemId',
    {
      preHandler: [guard],
      schema: { params: { type: 'object', properties: { itemId: { type: 'string', format: 'uuid' } }, required: ['itemId'] } },
    },
    async (request, reply) => {
      const { itemId } = request.params as { itemId: string };
      const removed = await opts.repo.remove(itemId);
      if (!removed) {
        reply.status(404);
        return { error: { code: 'NOT_FOUND', message: 'Item ' + itemId + ' does not exist', requestId: request.id, details: null } };
      }
      reply.status(204);
      return null;
    },
  );
}
`
  );
}

function appTs(ctx) {
  return (
    `// app.ts — Fastify assembly: dev-profile CORS (conventions/07), shared error
// envelope (conventions/04), JSON logs (conventions/03), health naked + mirror
// (conventions/02 rule 6), CRUD /items under /api/` +
    ctx.name +
    `.
// Dependencies are injected via opts → unit tests need no real database. Generated by gen-service.
import Fastify, { type FastifyBaseLogger, type FastifyError, type FastifyInstance } from 'fastify';
import cors from '@fastify/cors';
import type { Env } from './env.js';
import { ` +
    ctx.camel +
    `Logger } from './logger.js';
import { registerHealthRoutes } from './routes/health.js';
import { registerItemRoutes } from './routes/items.js';
import type { ItemsRepo } from './repo.js';

export interface AppDeps {
  env: Env;
  /** Repository — inject an in-memory fake in tests; server.ts wires the pg implementation. */
  repo: ItemsRepo;
}

export function buildApp(deps: AppDeps): FastifyInstance {
  const { env, repo } = deps;
  const logger = ` +
    ctx.camel +
    `Logger(env.logLevel);

  const app = Fastify({
    // pino ≥9.14 Logger type ≠ FastifyBaseLogger (msgPrefix) — cast the interface only;
    // the instance keeps the pino shape of conventions/03 (node-svc pattern).
    loggerInstance: logger as unknown as FastifyBaseLogger,
    genReqId: (req) => {
      // X-Request-Id from the gateway (conventions/03) — cross gateway→service tracing
      const header = req.headers['x-request-id'];
      return typeof header === 'string' && header.length > 0 ? header : crypto.randomUUID();
    },
    bodyLimit: 64 * 1024,
  });

  // CORS dev-profile — conventions/07: origins from CORS_DEV_ORIGIN (comma-separated);
  // empty (compose/prod) → origin:false = NO ACAO emitted (deny-by-default).
  const devOrigins = env.corsDevOrigin
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  void app.register(cors, {
    origin: devOrigins.length > 0 ? devOrigins : false,
    methods: ['GET', 'POST', 'PATCH', 'DELETE'],
    allowedHeaders: ['Authorization', 'Content-Type', 'X-Request-Id'],
  });

  // Shared error envelope (conventions/04) — maps every error, including FST_ERR_*.
  app.setErrorHandler((err: FastifyError, request, reply) => {
    const isValidation = Array.isArray(err.validation);
    const status = err.statusCode && err.statusCode >= 400 ? err.statusCode : isValidation ? 400 : 500;
    request.log[status >= 500 ? 'error' : 'warn']({ err: err.message }, 'request failed');
    reply.status(status).send({
      error: {
        code: isValidation
          ? 'VALIDATION_ERROR'
          : (err.code ?? (status === 401 ? 'UNAUTHORIZED' : status === 404 ? 'NOT_FOUND' : 'INTERNAL')),
        message: status >= 500 ? 'Internal error' : err.message,
        requestId: request.id,
        details: status >= 500 ? null : (err.validation ?? null),
      },
    });
  });

  // 404 outside routes — same envelope (NOT_FOUND).
  app.setNotFoundHandler((request, reply) => {
    reply.status(404).send({
      error: { code: 'NOT_FOUND', message: 'Route ' + request.method + ' ' + request.url + ' does not exist', requestId: request.id, details: null },
    });
  });

  // Health: naked (compose healthcheck + boot-smoke) + mirror /api/` +
    ctx.name +
    `/*.
  const ready = (): Promise<void> => repo.ping();
  registerHealthRoutes(app, { check: ready });
  app.register(
    async (scope) => {
      registerHealthRoutes(scope, { check: ready });
    },
    { prefix: '/api/` +
    ctx.name +
    `' },
  );

  // CRUD /api/` +
    ctx.name +
    `/items — default resource; replace with the real domain per the contract.
  app.register(
    async (scope) => {
      registerItemRoutes(scope, { jwtSecret: env.jwtSecret, repo });
    },
    { prefix: '/api/` +
    ctx.name +
    `' },
  );

  return app;
}
`
  );
}

